"""JWT 발급/검증 (pyjwt, HS256)."""
import os
import time

import jwt


_DEFAULT_SECRET = "dev-insecure-secret-change-me-in-production-32b"
_MIN_SECRET_LEN = 32
_ALG = "HS256"
_ISSUER = "saju-auth"


def _secret() -> str:
    s = os.environ.get("SAJU_JWT_SECRET", "").strip()
    is_prod = os.environ.get("SAJU_ENV", "").lower() == "production"

    if is_prod:
        if not s:
            raise RuntimeError(
                "SAJU_JWT_SECRET must be set in production. "
                "The default development secret must not be used in deployment."
            )
        if len(s) < _MIN_SECRET_LEN:
            raise RuntimeError(
                f"SAJU_JWT_SECRET must be at least {_MIN_SECRET_LEN} characters "
                f"in production (got {len(s)}). "
                f"Generate one with: openssl rand -hex 32"
            )
        return s

    if s:
        return s
    return _DEFAULT_SECRET


def ttl_seconds() -> int:
    try:
        return int(os.environ.get("SAJU_JWT_TTL_SECONDS", str(60 * 60 * 24 * 30)))
    except ValueError:
        return 60 * 60 * 24 * 30


def encode_token(user_id: str) -> str:
    now = int(time.time())
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + ttl_seconds(),
        "iss": _ISSUER,
    }
    return jwt.encode(payload, _secret(), algorithm=_ALG)


def decode_token(token: str) -> dict:
    return jwt.decode(
        token, _secret(), algorithms=[_ALG], issuer=_ISSUER,
    )
